// src/admin.js — privileged surface (recovered from sourcemap)
export function adminPanel(user) {
  if (user.isAdmin || user.role === 'superuser') {
    http.put('/api/v1/admin/users/:userId/role', { role: user.newRole });
    http.delete('/api/v1/admin/orders/:orderId');
    http.get('/api/v1/admin/reports/:reportId');
  }
}
export const featureFlagAdminBulkDelete = true;
export const enableInternalBilling = false;
